def sha256(path: Path) -> str:
    with Path(path).open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest()


@dataclass(frozen=True)
class Config:
    method: str = "shared_ssl"
    seed: int = 7
    history: int = 96
    pretrain_updates: int = 6000
    readout_updates: int = 500
