def source_paths(config):
    """Exact static local closure and pinned author source; no dynamic imports."""
    package = Path(core.__file__).resolve().parents[1]
    own = Path(__file__).resolve().parents[1]
    pending = [Path(__file__), own / "inference/native_cf_controls.py", Path(downstream.__file__),
               package / "inference/native_acoustic.py", package / "data/native_ssl_corpus.py",
               package / "training/aeon_corpus.py", package / "evaluation/native_product.py"]
    found = set()
    while pending:
        path = regular(pending.pop())
        if path in found:
            continue
        found.add(path)
        for node in ast.walk(ast.parse(path.read_bytes())):
            names = [a.name for a in node.names] if isinstance(node, ast.Import) else ([node.module] + [node.module + "." + a.name for a in node.names] if isinstance(node, ast.ImportFrom) and node.module else [])
            for name in names:
                if name.startswith("marine_echo.") or name == "marine_echo":
                    parts = name.split(".")[1:]
                    for count in range(len(parts) + 1):
                        base = package / Path(*parts[:count])
                        if name in ("marine_echo.training.native_cf_controls", "marine_echo.inference.native_cf_controls"):
                            base = own / Path(*parts[:count])
                        for file in (base.with_suffix(".py"), base / "__init__.py"):
                            if file.is_file():
                                pending.append(file)
    return sorted(found | set(core.required_sources(core_config(config))))


def required_paths(inputs, config):
    paths = [*source_paths(config), *(getattr(inputs, key) for key in ("train", "dev", "train_cohort", "dev_cohort", "split", "adr0016", "protocol", "config", "executor", "budget")), ROOT / "docs/adr/0022-cf-backbone-matched-controls.md", ROOT / "docs/adr/0025-cf-matched-controls-continuation.md", ROOT / "orchestration/ssl_vnext_cf_matched_controls_builder_contract.txt", ROOT / "tools/native_reference_supervisor.py"]
    return list(dict.fromkeys(regular(p) for p in paths))


def _synthetic_identity(inputs):
    allowed = Path(__file__).resolve().parents[3] / "evidence/ssl-cf-controls-builder-v1"
    parents = {regular(getattr(inputs, key)).parent for key in ("train", "dev", "train_cohort", "dev_cohort", "split", "config", "review", "executor", "budget")}
    if len(parents) != 1 or not next(iter(parents)).is_relative_to(allowed) or not next(iter(parents)).name.startswith(SYNTHETIC + "-"):
